function addSample(x){const key=`${x.source}:${x.seq}`;if(S.seen.has(key))return false;S.seen.set(key,1);const recv=Number(x.hostMs)||now(),dev=Number(x.deviceMs);if(Number.isFinite(dev)){if(S.lastDeviceMs!==null&&dev+5000<Number(S.lastDeviceMs))S.clockOffsetMs=null;S.lastDeviceMs=dev;const observed=recv-dev;if(S.clockOffsetMs===null||observed<S.clockOffsetMs)S.clockOffsetMs=observed;else S.clockOffsetMs=S.clockOffsetMs*.998+observed*.002;x.receiveMs=recv;x.hostMs=dev+S.clockOffsetMs;}if(S.lastSeq!==null&&Number.isFinite(Number(x.seq))){const gap=(Number(x.seq)-Number(S.lastSeq)-1)&0xffff;if(gap>0&&gap<32768)S.dropped+=gap;}S.lastSeq=x.seq;S.samples.push(x);S.packets++;S.lastPacketMs=x.hostMs||recv;S.phase=x.phase||S.phase;if(x.releaseMarker&&!S.prevRelease)registerSensorEvent('release',x);if(x.letdownMarker&&!S.prevLetdown)registerSensorEvent('letdown',x);S.prevRelease=!!x.releaseMarker;S.prevLetdown=!!x.letdownMarker;if(S.recording&&S.run&&S.runSamples.length<MAX_RUN_SAMPLES)S.runSamples.push({...x});trimRing();return true;}

function openDb(){return new Promise((res,rej)=>{const q=indexedDB.open(DB,1);q.onupgradeneeded=()=>{const db=q.result;if(!db.objectStoreNames.contains(SENSOR_STORE))db.createObjectStore(SENSOR_STORE,{keyPath:'id'});if(!db.objectStoreNames.contains(LINK_STORE))db.createObjectStore(LINK_STORE,{keyPath:'key'});};q.onsuccess=()=>res(q.result);q.onerror=()=>rej(q.error);});}
