async function dbAll(store){const db=await openDb();return new Promise((res,rej)=>{const q=db.transaction(store,'readonly').objectStore(store).getAll();q.onsuccess=()=>res(q.result||[]);q.onerror=()=>rej(q.error);});}
function openRunDb(){return new Promise((res,rej)=>{const q=indexedDB.open(RUN_DB,1);q.onupgradeneeded=()=>{const db=q.result;if(!db.objectStoreNames.contains(RUN_STORE))db.createObjectStore(RUN_STORE,{keyPath:'id'});};q.onsuccess=()=>res(q.result);q.onerror=()=>rej(q.error);});}
