function seqQuality(rows){if(rows.length<2)return 0;let gaps=0,expected=0;for(let i=1;i<rows.length;i++){const d=(Number(rows[i].seq)-Number(rows[i-1].seq))&0xffff;if(d>0&&d<32768){expected+=d;gaps+=Math.max(0,d-1);}}return expected?Math.max(0,1-gaps/expected):1;}
