function integrate(rows,getter){let total=0;for(let i=1;i<rows.length;i++){const dt=Math.max(0,Math.min(.05,(rows[i].hostMs-rows[i-1].hostMs)/1000));total+=((getter(rows[i])+getter(rows[i-1]))/2)*dt;}return total;}
