function motionScores(m,isLetdown){const clamp=x=>Math.max(0,Math.min(100,Math.round(x)));const hold=clamp(100-(m.holdRmsDps||0)*11-(m.aimDriftDeg||0)*5);if(isLetdown)return{hold,release:null,response:null,motionIndex:hold};const release=clamp(100-(m.releaseDisturbanceDeg||0)*10-Math.abs(m.cantReleaseDeg||0)*1.5);const response=clamp(100-(m.followMeanDps||0)*2.2-Math.abs(m.bowRotationDeg||0)*1.7);return{hold,release,response,motionIndex:clamp(hold*.45+release*.30+response*.25)};}
