function renderMarkers(){const e=$('#ecoMarkers');if(!e)return;const rows=[...S.linked.values()].sort((a,b)=>b.shotNo-a.shotNo).slice(0,8);e.innerHTML=rows.length?rows.map(r=>`<span class="eco-marker">#${r.shotNo} ↔ Sensor · Δ ${Math.round(r.syncDeltaMs)} ms</span>`).join(''):'<span class="muted">No linked camera shots yet.</span>';}

function drawTimeline(c,rows){if(!c||!rows?.length)return;const rect=c.getBoundingClientRect(),dpr=Math.min(2,devicePixelRatio||1),w=Math.max(300,Math.round(rect.width*dpr)),h=180*dpr;c.width=w;c.height=h;const g=c.getContext('2d');g.clearRect(0,0,w,h);g.strokeStyle='#294259';for(let i=1;i<4;i++){g.beginPath();g.moveTo(0,h*i/4);g.lineTo(w,h*i/4);g.stroke();}const mx=Math.max(8,...rows.map(gyroMag)),minT=rows[0].offsetMs??(rows[0].hostMs-rows[0].hostMs),maxT=rows.at(-1).offsetMs??(rows.at(-1).hostMs-rows[0].hostMs);g.strokeStyle='#46a7ff';g.lineWidth=2*dpr;g.beginPath();rows.forEach((x,i)=>{const off=x.offsetMs??(x.hostMs-rows[0].hostMs),xx=(off-minT)/Math.max(1,maxT-minT)*w,yy=h-(gyroMag(x)/mx*(h*.8)+h*.08);i?g.lineTo(xx,yy):g.moveTo(xx,yy)});g.stroke();if(minT<=0&&maxT>=0){const zero=(0-minT)/Math.max(1,maxT-minT)*w;g.strokeStyle='#f0cc55';g.lineWidth=1.5*dpr;g.beginPath();g.moveTo(zero,0);g.lineTo(zero,h);g.stroke();}}

async function startRecording(){const c=ctx();if(!S.connected||!c.sessionId)return;S.recording=true;S.run={id:`run-${c.sessionId}-${now()}`,startedAt:new Date().toISOString(),startedMs:now(),sessionId:c.sessionId,athleteId:Number(c.athlete?.id)||null,deviceId:S.deviceId,dataMode:S.dataMode};S.runSamples=[];renderRecording();}
